dashboard.definition:
{
  "title": "Santé et performance AD",
  "description": "Santé et performance des contrôleurs de domaine : état AD, événements Netlogon et DNS signalant des problèmes, fraîcheur des données par DC, et compteurs Perfmon NTDS (LDAP, file de réplication, threads), CPU, DNS et dossiers répliqués DFS.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Période",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    },
    "input_pm_st": {
      "type": "input.dropdown",
      "title": "Sourcetype Perfmon",
      "options": {
        "token": "pm_st",
        "defaultValue": "Perfmon:NTDS",
        "items": [
          {
            "label": "NTDS",
            "value": "Perfmon:NTDS"
          },
          {
            "label": "DNS",
            "value": "Perfmon:DNS"
          },
          {
            "label": "Dossiers répliqués DFS",
            "value": "Perfmon:DFS_Replicated_Folders"
          },
          {
            "label": "Interface réseau",
            "value": "Perfmon:Network_Interface"
          },
          {
            "label": "Processeur",
            "value": "Perfmon:Processor"
          }
        ]
      }
    },
    "input_pm_counter": {
      "type": "input.dropdown",
      "title": "Compteur",
      "options": {
        "token": "pm_counter",
        "selectFirstSearchResult": true
      },
      "dataSources": {
        "primary": "ds_counters"
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "title": "DC qui remontent leur état",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "DC en problème",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "SYSVOL non partagé",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "Serveurs DNS en problème",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "Catalogues globaux",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "title": "Clients sans site AD (24 h)",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_7": {
      "type": "splunk.singlevalue",
      "title": "Sources silencieuses (aucune donnée > 60 min)",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_8": {
      "type": "splunk.table",
      "title": "Contrôleurs de domaine - santé, rôles et inventaire",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "count": 12,
        "wrap": true,
        "columnFormat": {
          "Statut": {
            "rowBackgroundColors": "> table | seriesByName(\"Statut\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "description": "Dernier état MSAD:NT6:Health de chaque DC. PROBLÈME = SYSVOL non partagé, processus non OK, enregistrement DNS en échec ou service surveillé arrêté (ntfrs est ignoré : normalement arrêté avec DFSR). fsmo = rôles FSMO détenus ; istg = générateur de topologie inter-sites.",
      "context": {
        "col0ColorConfig": [
          {
            "match": "OK",
            "value": "#65A637"
          },
          {
            "match": "PROBLÈME",
            "value": "#B0413E"
          }
        ]
      }
    },
    "viz_9": {
      "type": "splunk.pie",
      "title": "Contrôleurs de domaine par système d'exploitation",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_10": {
      "type": "splunk.bar",
      "title": "Contrôleurs de domaine par site AD",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_11": {
      "type": "splunk.table",
      "title": "Détenteurs des rôles FSMO",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "count": 6,
        "wrap": true
      }
    },
    "viz_12": {
      "type": "splunk.table",
      "title": "Serveurs DNS - santé",
      "dataSources": {
        "primary": "ds_12"
      },
      "options": {
        "count": 8,
        "wrap": true,
        "columnFormat": {
          "Statut": {
            "rowBackgroundColors": "> table | seriesByName(\"Statut\") | matchValue(col0ColorConfig)"
          }
        }
      },
      "description": "Dernier état MSAD:NT6:DNS-Health de chaque serveur DNS (état du service, DNSSEC, récursion, intervalle de nettoyage, redirecteurs).",
      "context": {
        "col0ColorConfig": [
          {
            "match": "OK",
            "value": "#65A637"
          },
          {
            "match": "PROBLÈME",
            "value": "#B0413E"
          }
        ]
      }
    },
    "viz_13": {
      "type": "splunk.line",
      "title": "USN max par DC (activité de modification de l'annuaire)",
      "dataSources": {
        "primary": "ds_13"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_14": {
      "type": "splunk.column",
      "title": "Affinité de site Netlogon dans le temps",
      "dataSources": {
        "primary": "ds_14"
      },
      "options": {
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      }
    },
    "viz_15": {
      "type": "splunk.table",
      "title": "Sous-réseaux absents d'AD Sites and Services (NO_CLIENT_SITE)",
      "dataSources": {
        "primary": "ds_15"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "description": "Clients qui s'authentifient depuis une IP absente de tout sous-réseau AD (Netlogon NO_CLIENT_SITE) : ils peuvent être servis par un DC distant. Ajoutez ces sous-réseaux au bon site dans AD Sites and Services. Le regroupement en /24 est une approximation."
    },
    "viz_16": {
      "type": "splunk.table",
      "title": "Clients sans site AD - principaux hôtes",
      "dataSources": {
        "primary": "ds_16"
      },
      "options": {
        "count": 10,
        "wrap": true
      }
    },
    "viz_17": {
      "type": "splunk.table",
      "title": "Fraîcheur des données par DC et par source (minutes depuis le dernier événement)",
      "dataSources": {
        "primary": "ds_17"
      },
      "options": {
        "count": 15,
        "wrap": true
      },
      "description": "Cellule vide = ce DC n'a jamais envoyé cette source au cours des dernières 24 h."
    },
    "viz_18": {
      "type": "splunk.line",
      "title": "NTDS - recherches LDAP/s",
      "dataSources": {
        "primary": "ds_18"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_19": {
      "type": "splunk.line",
      "title": "NTDS - opérations de réplication en attente",
      "dataSources": {
        "primary": "ds_19"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_20": {
      "type": "splunk.line",
      "title": "NTDS - threads DS utilisés",
      "dataSources": {
        "primary": "ds_20"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_21": {
      "type": "splunk.line",
      "title": "CPU - % temps processeur (_Total)",
      "dataSources": {
        "primary": "ds_21"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_22": {
      "type": "splunk.line",
      "title": "DNS - requêtes reçues/s",
      "dataSources": {
        "primary": "ds_22"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_23": {
      "type": "splunk.line",
      "title": "DNS - échecs de requêtes récursives/s",
      "dataSources": {
        "primary": "ds_23"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_24": {
      "type": "splunk.line",
      "title": "Explorateur Perfmon : choisissez un compteur",
      "dataSources": {
        "primary": "ds_24"
      },
      "options": {
        "legendDisplay": "bottom"
      },
      "description": "Choisissez un sourcetype Perfmon puis un compteur (NTDS, DNS, Dossiers répliqués DFS, Interface réseau, Processeur)."
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "DC qui remontent leur état",
      "options": {
        "query": "`adx_dc_health` | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "DC en problème",
      "options": {
        "query": "`adx_dc_health` | where status=\"PROBLÈME\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "SYSVOL non partagé",
      "options": {
        "query": "`adx_dc_health` | where sysvol!=\"True\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Serveurs DNS en problème",
      "options": {
        "query": "`adx_dns_health` | where status=\"PROBLÈME\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Catalogues globaux",
      "options": {
        "query": "`adx_dc_health` | where gc=\"True\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Clients sans site AD (24 h)",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" msad_affinity=NO_CLIENT_SITE | stats dc(src_ip)",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Sources silencieuses (aucune donnée > 60 min)",
      "options": {
        "query": "| multisearch [search `adx_msad_index` (sourcetype=\"MSAD:NT6:Health\" OR sourcetype=\"MSAD:NT6:Replication\" OR sourcetype=\"MSAD:NT6:Netlogon\" OR sourcetype=\"MSAD:NT6:DNS-Health\") | fields host sourcetype _time] [search `adx_perfmon_index` (sourcetype=\"Perfmon:NTDS\" OR sourcetype=\"Perfmon:Processor\") | fields host sourcetype _time] | stats max(_time) as last by host sourcetype | where last<now()-3600 | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Contrôleurs de domaine - santé, rôles et inventaire",
      "options": {
        "query": "`adx_dc_health` | eval last_report=minutes_ago.\" min ago\", problem=coalesce(mvjoin(problem,\"; \"),\"-\") | sort - status, site, Server | table site Server status problem os gc rodc fsmo istg sysvol procs_ok dns_register svc_down usn forest_level domain_level schema last_report | rename site as \"Site\", Server as \"Serveur\", status as \"Statut\", problem as \"Problème\", os as \"OS\", gc as \"GC\", rodc as \"RODC\", fsmo as \"Rôles FSMO\", istg as \"ISTG\", sysvol as \"SYSVOL\", procs_ok as \"Processus OK\", dns_register as \"Enregistrement DNS\", svc_down as \"Services arrêtés\", usn as \"USN max\", forest_level as \"Niveau forêt\", domain_level as \"Niveau domaine\", schema as \"Schéma\", last_report as \"Dernier rapport\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Contrôleurs de domaine par système d'exploitation",
      "options": {
        "query": "`adx_dc_health` | stats count by os",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "Contrôleurs de domaine par site AD",
      "options": {
        "query": "`adx_dc_health` | stats count by site",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Détenteurs des rôles FSMO",
      "options": {
        "query": "`adx_dc_health` | where len(fsmo)>0 | table Server fsmo site | rename Server as \"Serveur\", fsmo as \"Rôles FSMO\", site as \"Site\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "Serveurs DNS - santé",
      "options": {
        "query": "`adx_dns_health` | eval problem=coalesce(mvjoin(problem,\"; \"),\"-\"), forwarders=mvjoin(forwarders,\", \"), last_report=minutes_ago.\" min ago\" | sort - status, Server | table Server status problem dns_status started dnssec no_recursion scavenging_h forwarders os last_report | rename Server as \"Serveur\", status as \"Statut\", problem as \"Problème\", dns_status as \"Statut DNS\", started as \"Démarré\", dnssec as \"DNSSEC\", no_recursion as \"Sans récursion\", scavenging_h as \"Nettoyage (h)\", forwarders as \"Redirecteurs\", os as \"OS\", last_report as \"Dernier rapport\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "USN max par DC (activité de modification de l'annuaire)",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Health\" | timechart span=1h max(HighestUSN) by Server limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_14": {
      "type": "ds.search",
      "name": "Affinité de site Netlogon dans le temps",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" | fillnull value=\"OTHER\" msad_affinity | timechart span=1h count by msad_affinity",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_15": {
      "type": "ds.search",
      "name": "Sous-réseaux absents d'AD Sites and Services (NO_CLIENT_SITE)",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" msad_affinity=NO_CLIENT_SITE | eval subnet=replace(src_ip,\"^(\\d+\\.\\d+\\.\\d+)\\.\\d+\",\"\\1.0/24\") | stats count as requests, dc(src_ip) as clients, dc(src_host) as hosts, values(host) as seen_by_dc, latest(src_host) as sample_host by subnet | sort - requests | table subnet requests clients hosts seen_by_dc sample_host | rename subnet as \"Sous-réseau\", requests as \"Requêtes\", clients as \"Clients\", hosts as \"Hôtes\", seen_by_dc as \"Vu par les DC\", sample_host as \"Hôte exemple\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_16": {
      "type": "ds.search",
      "name": "Clients sans site AD - principaux hôtes",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" msad_affinity=NO_CLIENT_SITE | stats count as requests, latest(src_ip) as src_ip, latest(src_domain) as domain, values(host) as seen_by_dc by src_host | sort - requests | table src_host requests src_ip domain seen_by_dc | rename src_host as \"Hôte source\", requests as \"Requêtes\", src_ip as \"IP source\", domain as \"Domaine\", seen_by_dc as \"Vu par les DC\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_17": {
      "type": "ds.search",
      "name": "Fraîcheur des données par DC et par source (minutes depuis le dernier événement)",
      "options": {
        "query": "| multisearch [search `adx_msad_index` (sourcetype=\"MSAD:NT6:Health\" OR sourcetype=\"MSAD:NT6:Replication\" OR sourcetype=\"MSAD:NT6:Netlogon\" OR sourcetype=\"MSAD:NT6:DNS-Health\") | fields host sourcetype _time] [search `adx_perfmon_index` (sourcetype=\"Perfmon:NTDS\" OR sourcetype=\"Perfmon:Processor\" OR sourcetype=\"Perfmon:DNS\" OR sourcetype=\"Perfmon:DFS_Replicated_Folders\") | fields host sourcetype _time] | stats max(_time) as last by host sourcetype | eval minutes_ago=round((now()-last)/60,0) | chart latest(minutes_ago) as m over host by sourcetype | rename host as \"DC\"",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_18": {
      "type": "ds.search",
      "name": "NTDS - recherches LDAP/s",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:NTDS\" counter=\"LDAP Searches/sec\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_19": {
      "type": "ds.search",
      "name": "NTDS - opérations de réplication en attente",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:NTDS\" counter=\"DRA Pending Replication Operations\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_20": {
      "type": "ds.search",
      "name": "NTDS - threads DS utilisés",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:NTDS\" counter=\"DS Threads in Use\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_21": {
      "type": "ds.search",
      "name": "CPU - % temps processeur (_Total)",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:Processor\" counter=\"% Processor Time\" instance=\"_Total\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_22": {
      "type": "ds.search",
      "name": "DNS - requêtes reçues/s",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:DNS\" counter=\"Total Query Received/sec\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_23": {
      "type": "ds.search",
      "name": "DNS - échecs de requêtes récursives/s",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:DNS\" counter=\"Recursive Query Failure/sec\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_24": {
      "type": "ds.search",
      "name": "Explorateur Perfmon : choisissez un compteur",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"$pm_st$\" counter=\"$pm_counter$\" | eval series=host.\" \".coalesce(instance,\"\") | timechart span=5m avg(Value) by series limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_counters": {
      "type": "ds.search",
      "name": "Perfmon counters",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"$pm_st$\" | stats count by counter | eval label=counter, value=counter | sort label | fields label value",
